using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"Expected {expected} but got {result}");
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Tax rate below 0")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> ApplyDiscountValidCases
    {
        get
        {
            yield return [100.00m, 0m, 100.00m, "No discount"];
            yield return [100.00m, 10m, 90.00m, "10% off"];
            yield return [100.00m, 50m, 50.00m, "50% off"];
            yield return [100.00m, 100m, 0.00m, "100% off (free)"];
            yield return [59.99m, 25m, 44.9925m, "Fractional result"];
            yield return [0.00m, 50m, 0.00m, "Zero price with discount"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountValidCases))]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Scenario: {scenario}");
    }

    public static IEnumerable<object[]> ApplyDiscountInvalidCases
    {
        get
        {
            yield return [100.00m, -1m, "Below zero"];
            yield return [100.00m, 100.01m, "Above 100"];
            yield return [50.00m, -50m, "Large negative"];
            yield return [50.00m, 200m, "Well above 100"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountInvalidCases))]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent, string scenario)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName, $"Scenario: {scenario}");
    }

    // --- DynamicData from a method (alternative pattern) ---

    public static IEnumerable<object[]> GetCalculateTotalBoundaryData()
    {
        yield return [0.01, 1, 0.0, 0.01, "Minimum meaningful price"];
        yield return [9999.99, 100, 1.0, 1999998.00, "Large order, max tax"];
        yield return [0.01, 1, 1.0, 0.02, "Min price, max tax"];
    }

    [TestMethod]
    [DynamicData(nameof(GetCalculateTotalBoundaryData), DynamicDataSourceType.Method)]
    public void CalculateTotal_BoundaryValues_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected, string scenario)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"Scenario: {scenario}");
    }
}

